#include <Arduino.h>
#include <Servo.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
Servo servo1;
Servo servo2;
Servo servo3;
const byte segmentCodes[] = {
  0b11000000,
  0b11111001,
  0b10100100,
  0b10110000,
  0b10011001,
  0b10010010,
  0b10000010,
  0b11111000,
  0b10000000,
  0b10010000,
};
int currentNumber = 0;

void setup();
void loop();
void displayNumber(int number);
void updateServos(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  servo1.attach(2);  
  servo2.attach(3);  
  servo3.attach(4);  
  displayNumber(currentNumber);
  updateServos(currentNumber);
}
void loop() {
  delay(2000); 
  currentNumber++;
  if (currentNumber > 99) {
    currentNumber = 0;
  }
  displayNumber(currentNumber);
  updateServos(currentNumber);
}
void displayNumber(int number) {
  int tens = number / 10;
  int ones = number % 10;
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void updateServos(int number) {
  servo1.write(number * 1.8);
  servo2.write(number * 1.2);
  servo3.write(number * 0.6);
}
